// live effective-strength heuristics - mirror the engine's log-odds terms, mapped to a 0-100 display scale
function effBat(bat,bowl,ctx){
  const tc=typeClass(bowl.bowlType||'fastMedium');
  let v=bat.bat+CAL.matchup*(((tc==='pace'?(bat.vsPace??50):(bat.vsSpin??50)))-50);
  v-=16*Math.exp(-(ctx.faced??30)/CAL.setness_scale);
  v+=((bat.formIx??3)-3)*1.2-(bat.fatigue==='tired'?2:0);
  const T=bat.talents||[];
  if(T.includes('fastStarter'))v+=8*Math.exp(-(ctx.faced??30)/CAL.setness_scale);
  if(T.includes('finisher')&&(ctx.over??20)>=40)v+=4;
  if(T.includes('anchor')&&(ctx.rrDef??0)<=0)v+=3;
  if((ctx.pitch==='flat'))v+=4;if(ctx.pitch==='twoPaced'||ctx.pitch==='cracked')v-=4;
  if(ctx.weather==='hot')v+=2;if(ctx.weather==='drizzle')v-=2;
  return Math.max(5,Math.min(97,Math.round(v)));
}
function effBowl(bat,bowl,ctx){
  const tc=typeClass(bowl.bowlType||'fastMedium');
  const nb=Math.exp(-(ctx.over??20)/8),grip=1/(1+Math.exp(-((ctx.over??20)-25)/8));
  let v=0.55*(bowl.threat||40)+0.45*(bowl.control||40);
  v+=((bowl.formIx??3)-3)*1.2-(bowl.fatigue==='tired'?2:0);
  if(tc==='pace'){v+=14*nb*(ctx.pitch==='green'?1.5:1);if(ctx.weather==='overcast')v+=4;if(ctx.weather==='humid')v+=5*nb}
  else{v+=14*grip*(ctx.pitch==='dry'?1.6:1)-8*nb;if(ctx.weather==='dew later'&&ctx.chase)v-=4}
  if(ctx.pitch==='cracked')v+=4;if(ctx.pitch==='twoPaced')v+=3;
  const T=bowl.talents||[];
  if(T.includes('newBallSpecialist'))v+=8*nb;
  if(T.includes('deathSpecialist')&&(ctx.over??20)>=40)v+=5;
  if(T.includes('partnershipBreaker')&&(ctx.pship??0)>=50)v+=5;
  return Math.max(5,Math.min(97,Math.round(v)));
}
function meter(v,lbl){const col=v>=70?'#2c7a2c':v>=45?'#c8a13a':'#a33328';
  return `<div style="margin:2px 0"><span class="sklbl">${lbl}</span><span class="bar" style="width:130px"><i style="width:${v}%;background:${col}"></i></span><span class="skword" style="color:${col}">${word(v)}</span></div>`}
const word=x=>WORDS[wIx(x)], abbr=x=>ABBR[wIx(x)];
const esc=t=>String(t).replace(/&/g,'&amp;').replace(/</g,'&lt;');
const $=s=>document.querySelector(s);
const userTeam=()=>GD.teams[App.teamIx];
const PITCHTIP={balanced:'Balanced surface - no strong bias to bat or ball.',flat:'Flat road - favours batters; big scores likely.',green:'Green top - seamers get movement, especially with the new ball.',dry:'Dry, dusty - spinners grip and turn from mid-innings.',slow:'Slow and low - hard to hit through the line; sixes are rare.',cracked:'Cracked - variable bounce brings edges and wickets all day.',twoPaced:'Two-paced - inconsistent pace makes timing difficult.'};
const WXTIP={Sunny:'Clear and true - neutral conditions.',Overcast:'Cloud cover assists swing bowling.',Humid:'Humidity helps the ball swing through the air.',Hot:'Heat tires bowlers faster and aids spin later.',Scorching:'Extreme heat drains stamina quickly; spin grows sharper.',Drizzle:'Damp ball favours seam; batting is trickier.',Windy:'Wind unsettles length and can carry catches.',Chilly:'Cold, hard ball helps seamers hold their nip.',Misty:'Mist keeps the new ball dangerous longer.','Dew later':'Dew later eases batting and helps chasing sides.'};
const wxTip=w=>WXTIP[w]||'Match-day conditions.';const pitchTip=p=>PITCHTIP[p]||'A fair surface.';
const GPITCH={'Headingley':'green','The Oval':'balanced','Wankhede Stadium':'flat','M. Chinnaswamy Stadium':'twoPaced','Sydney Cricket Ground':'dry','Eden Park':'balanced','SuperSport Park':'green','National Stadium':'slow',"Queen's Park Oval":'dry','Basin Reserve':'cracked'};
function groundPitch(g){const t=GD.teams.find(x=>x.ground===g);return (t&&t.homePitch)||GPITCH[g]||'balanced'}
function econInit(){
  if(App.fin)return;
  App.fin={bank:500000,ledger:[]};
  App.seasonNo=1;App.history=[];
  App.market={listed:[],myBids:{},round:-1};
  App.cup={stage:0,alive:null,results:[],out:false};
  for(const t of GD.teams){t.acadY=t.acadY||2;t.acadS=t.acadS||2;t.seats=t.seats||9000;
    t.supporters=t.supporters||2600;t.mood=t.mood??3;t.homePitch=t.homePitch||groundPitch(t.ground);t.bank=t.bank||500000;}
}
function playerValue(p){return Math.max(8000,Math.round(p.wage*34+(p.rating-3200)*18))}
function roleClass(p){return p.bowlType?(p.role==='allRounder'?'ar':'bowl'):(p.role==='wicketkeeper'?'wk':'bat')}
function clubNeed(t,rc){ // weaker area = bigger need multiplier
  const xi=pickXI(t);
  const bat=xi.slice(0,7).reduce((a,p)=>a+aggBat(p),0)/7;
  const bw=xi.filter(p=>p.bowlType);const bowl=bw.reduce((a,p)=>a+aggBowl(p),0)/Math.max(1,bw.length);
  if(rc==='bat'||rc==='wk')return bat<bowl?1.25:0.9;
  if(rc==='bowl')return bowl<bat?1.25:0.9;
  return 1.05;}
function genListings(){
  econInit();const S=App.season;if(App.market.round===S.round)return;
  App.market.round=S.round;
  const keep=App.market.listed.filter(l=>l.seller===userTeam().name); // user listings persist till resolved
  App.market.listed=keep;
  let h=(S.round*2654435761)>>>0;const rnd=()=>((h=(h*1103515245+12345)>>>0)/4294967296);
  const pool=[];
  for(let i=0;i<GD.teams.length;i++){if(i===App.teamIx)continue;
    for(const p of GD.teams[i].players)if(p.rating>3100)pool.push({p,club:i});}
  pool.sort(()=>rnd()-0.5);
  for(const c of pool.slice(0,8)){
    App.market.listed.push({name:c.p.name,seller:GD.teams[c.club].name,base:playerValue(c.p),deadline:S.round});}
}
function listOwnPlayer(nm,ask){econInit();
  if(App.market.listed.some(l=>l.name===nm))return;
  App.market.listed.push({name:nm,seller:userTeam().name,base:Math.max(1000,ask|0),deadline:App.season.round});
  pgMarket();}
function resolveMarket(){
  econInit();const S=App.season;const me=userTeam();const news=[];
  let h=(S.round*40503+7)>>>0;const rnd=()=>((h=(h*1103515245+12345)>>>0)/4294967296);
  for(const l of App.market.listed){
    const fp=findPlayer(l.name);if(!fp){continue}
    const rc=roleClass(fp.p);
    let best=null;
    for(let i=0;i<GD.teams.length;i++){
      const t=GD.teams[i];if(t.name===l.seller)continue;
      if(t.players.length>=18)continue;
      const isMe=(i===App.teamIx);
      if(isMe){const my=App.market.myBids[l.name]|0;
        if(my>=l.base&&my<=App.fin.bank&&(!best||my>best.amt))best={t,amt:my,me:true};
        continue;}
      const val=playerValue(fp.p)*clubNeed(t,rc)*(0.8+0.45*rnd());
      const amt=Math.round(val/500)*500;
      if(amt>=l.base&&amt<=t.bank*0.4&&(!best||amt>best.amt))best={t,amt,me:false};
    }
    if(best){
      const from=GD.teams.find(t=>t.name===l.seller);
      const ix=from.players.findIndex(p=>p.name===l.name);
      const[pl]=from.players.splice(ix,1);
      best.t.players.push(pl);
      if(best.me)ledger('Bought '+pl.name,-best.amt);else if(from===me)ledger('Sold '+pl.name,+best.amt);
      if(!best.me)best.t.bank-=best.amt;
      if(from!==me)from.bank+=best.amt;
      news.push(pl.name+' → '+best.t.name+' for $'+best.amt.toLocaleString());
    }
  }
  App.market.listed=[];App.market.myBids={};
  if(news.length)App.news=(news.map(n=>'TRANSFER: '+n)).concat(App.news||[]).slice(0,12);
}
// ---- Senior One Day Cup: prelims R3, QF R7, SF R12, Final R16 (after those league rounds complete) ----
const CUPROUNDS={3:'Preliminaries',7:'Quarter-finals',12:'Semi-finals',16:'Final'};
function cupSeeds(){ // league position order at first cup round
  const rows=leagueRows();const ix=nm=>GD.teams.findIndex(t=>t.name===nm);
  return rows.map(r=>ix(r.nm)).filter(i=>i>=0);
}
function cupTick(){ // called at completeRound AFTER league round increments? we call before ++ with S.round = just-played round
  econInit();const S=App.season;const C=App.cup;const rd=S.round+1; // human-numbered round just completed
  if(!CUPROUNDS[rd])return;
  if(C.alive===null){const seeds=cupSeeds();C.alive=seeds.length===10?seeds:GD.teams.map((_,i)=>i);}
  let pairs=[];
  if(rd===3){ // seeds 7-10 play in; 1-6 byes
    pairs=[[C.alive[6],C.alive[9]],[C.alive[7],C.alive[8]]];
    C.next=C.alive.slice(0,6);
  }else{
    const a=C.alive;pairs=[];for(let i=0;i<a.length/2;i++)pairs.push([a[i],a[a.length-1-i]]);
    C.next=[];
  }
  const winners=[];
  for(let i=0;i<pairs.length;i++){const f=pairs[i];
    const home=GD.teams[f[0]];
    const isUser=(f[0]===App.teamIx||f[1]===App.teamIx);
    const meta={home:home.name,away:GD.teams[f[1]].name,ground:home.ground,pitch:groundPitch(home.ground),
      weather:WXLIST[(rd*11+f[0])%WXLIST.length],seed:7700+rd*20+f[0],date:simDate(),comp:'cup',round:S.round,isUser:false};
    simBackground(f[0],f[1],meta);
    const r=App.results[App.results.length-1];
    const wIx=GD.teams.findIndex(t=>t.name===r.result.winner);
    winners.push(wIx);
    App.news=(['CUP ('+CUPROUNDS[rd]+'): '+r.result.text]).concat(App.news||[]).slice(0,12);
    if(isUser&&wIx!==App.teamIx)C.out=true;
  }
  C.alive=(C.next||[]).concat(winners);
  if(rd===16){C.champion=GD.teams[C.alive[0]].name;
    if(C.alive[0]===App.teamIx)ledger('Cup winners prize',120000);
    App.news=(['CUP FINAL: '+C.champion+' lift the Senior One Day Cup!']).concat(App.news||[]).slice(0,12);}
  C.results.push({rd,stage:CUPROUNDS[rd]});
}
function pgMarket(){
  econInit();seasonInit();genListings();
  const me=userTeam();
  const rows=App.market.listed.map(l=>{
    const fp=findPlayer(l.name);if(!fp)return '';
    const p=fp.p;const mine=l.seller===me.name;
    return `<tr><td>${playerLink(p)}${(p.talents&&p.talents.length)?' ★':''}</td><td>${prole(p.role)}</td><td class="n">${p.age|0}</td><td class="tt">${abbr(aggBat(p))}</td><td class="tt">${p.bowlType?abbr(aggBowl(p)):'-'}</td><td>${esc(l.seller)}</td><td class="n">$${l.base.toLocaleString()}</td>
    <td>${mine?'<span class="small">your listing</span>':`<input type="number" style="width:86px" value="${App.market.myBids[l.name]||''}" placeholder="bid" onchange="App.market.myBids['${esc(l.name)}']=+this.value">`}</td></tr>`}).join('');
  const own=me.players.slice().sort((a,b)=>b.rating-a.rating).map(p=>`<option value="${esc(p.name)}">${esc(p.name)} (val ~$${playerValue(p).toLocaleString()})</option>`).join('');
  $('#page').innerHTML=crumb(me.name,'Transfer market')+
  `<div class="panel"><h4>Listed players - auction resolves when you complete the round</h4><div class="pad">
    <table><tr><th>Player</th><th>Role</th><th class="n">Age</th><th>Bat</th><th>Bowl</th><th>Seller</th><th class="n">Reserve</th><th>Your bid</th></tr>${rows||'<tr><td colspan=8 class="small">No listings this round.</td></tr>'}</table>
    <div class="small" style="margin-top:4px">Bank: <b>$${App.fin.bank.toLocaleString()}</b>. Highest bid over reserve wins; AI clubs bid to need and budget. Winning bids are paid at round completion.</div>
  </div></div>
  <div class="panel"><h4>Sell a player</h4><div class="pad">
    <div class="ctlrow"><select id="mkSell">${own}</select>
    <span>Reserve $</span><input id="mkAsk" type="number" style="width:100px" value="20000">
    <button class="primary" onclick="listOwnPlayer(document.getElementById('mkSell').value,+document.getElementById('mkAsk').value)">List for sale</button></div>
    <div class="small">Listed players stay in your XI until sold. If nobody meets the reserve, they stay put.</div>
  </div></div>`;
}
const MOODW=['furious','angry','grumpy','content','pleased','delighted','euphoric'];
function ledger(label,amt){App.fin.bank+=amt;App.fin.ledger.unshift({wk:'S'+App.seasonNo+' R'+((App.season?App.season.round:0)+1),label,amt});if(App.fin.ledger.length>200)App.fin.ledger.pop()}
function attendance(t){return Math.min(t.seats,Math.round(t.supporters*(0.55+0.13*t.mood)))}
const findPlayer=nm=>{for(const t of GD.teams){for(const p of t.players)if(p.name===nm)return{p,team:t};for(const p of (t.youth||[]))if(p.name===nm)return{p,team:t,youth:true}}return null};
// grouped aggregates per spec
const S=p=>p.skills||{};
const aggBat=p=>Math.round(.25*S(p).vsPace+.25*S(p).vsSpin+.2*S(p).rotation+.15*S(p).temperament+.15*S(p).power);
const aggBowl=p=>p.bowlType?Math.round((S(p).wicket+S(p).economy+S(p).discipline+S(p).moveTurn+S(p).variation+S(p).stamina)/6):Math.round(S(p).wicket*0.3||5);
const aggKeep=p=>p.keeper?Math.round((S(p).keeping+S(p).stumping+S(p).catching)/3):Math.min(15,Math.round(S(p).keeping||8));
const aggTech=p=>Math.round((S(p).vsPace+S(p).vsSpin+S(p).temperament)/3);
const aggEnd=p=>p.bowlType?S(p).stamina:Math.round(S(p).temperament*0.9);
const aggField=p=>Math.round((S(p).fielding+S(p).catching)/2);
const isPT=p=>p.bowlTypeFull&&p.bowlTypeFull.startsWith('partTime');
const bar=(v,lbl)=>`<span class="sklbl" title="${TIPS[lbl]||lbl}">${lbl}</span><span class="bar"><i style="width:${Math.max(2,Math.min(100,v))}%"></i></span><span class="skword" title="${word(v)} - rank ${wIx(v)+1} of 16">${word(v)}</span>`;
function crumb(...parts){return `<div class="crumb">${parts.map(esc).join('<span class="sep">&raquo;</span>')}</div>`}
function playerTip(p){
  if(!p)return '';
  const hit=(typeof findPlayer==='function')?findPlayer(p.name):null;
  const team=hit&&hit.team?hit.team.name:(p.team||'');
  const bat=word(aggBat(p));
  const bowl=p.bowlType?word(aggBowl(p)):'does not bowl';
  const keep=p.keeper?(' · keeping '+word(aggKeep(p))):'';
  const tals=(p.talents&&p.talents.length)?(' · Talents: '+p.talents.map(ptal).join(', ')):'';
  return `${p.name}\nTeam: ${team||'-'}\n${p.hand==='L'?'Left':'Right'} hand bat · ${p.btLabel||'does not bowl'}\nAge: ${p.age} · Nat: ${p.nat} · Form: ${p.formWord||'-'} · Fatigue: ${p.fatigue||'-'}\nBatting: ${bat} · Bowling: ${bowl}${keep}\nExp: ${p.expWord||p.exp||'-'} · Captaincy: ${word(p.capt||30)} · Rating: ${p.rating}${tals}`;
}
function playerMini(p){return `<span class="player-hoverable" title="${esc(playerTip(p))}">${esc(p.name)}</span>`}
function playerLink(p){return `<a href="#/player?n=${encodeURIComponent(p.name)}" title="${esc(playerTip(p))}">${esc(p.name)}</a>`}

// ---------- router ----------
// A BLANK PAGE IS NOT AN OUTCOME. Whatever goes wrong - a renderer that
// throws, a renderer that runs and paints nothing - the manager must be told
// and must be given somewhere to go. Silence here reads as "the game is
// broken" and leaves no way to find out otherwise.
function foPageFailed(where,err,why){
  try{
    const el=document.getElementById('page'); if(!el)return;
    if(el.querySelector('.fo-page-failed'))return;              // already saying it
    const detail=err?String((err&&err.message)||err).slice(0,300):'';
    el.innerHTML='<div class="fo-page-failed" style="max-width:560px;margin:52px auto;padding:22px 24px;border:1px solid rgba(0,0,0,.14);border-radius:14px;background:rgba(255,255,255,.92)">'+
      '<h3 style="margin:0 0 10px">This page did not draw</h3>'+
      '<p style="margin:0 0 14px;line-height:1.55">'+esc(why||'Something went wrong drawing this page.')+
      ' Nothing is lost — your club and everything it has done are safe on the server. Try another page, or reload.</p>'+
      (detail?'<pre style="margin:0 0 14px;padding:8px 10px;border-radius:8px;background:rgba(0,0,0,.05);font-size:11px;line-height:1.5;white-space:pre-wrap;overflow-x:auto">'+esc(detail)+'</pre>':'')+
      '<div style="display:flex;gap:8px;flex-wrap:wrap">'+
      '<button onclick="location.hash=\'#/squad\'">Squad</button>'+
      '<button onclick="location.hash=\'#/fixtures\'">Fixtures</button>'+
      '<button class="primary" onclick="location.reload()">Reload</button></div></div>';
  }catch(e){}
}
// Some renderers paint on their own interval rather than during route(), so a
// page that is empty for an instant is normal. One that is STILL empty seconds
// later, with the route unchanged, is not.
let foBlankT=null;
function foBlankWatch(where){
  try{
    clearTimeout(foBlankT);
    foBlankT=setTimeout(function(){
      try{
        const el=document.getElementById('page');
        if(!el||App.page!==where)return;                        // moved on; not our business
        if(el.firstElementChild)return;                         // something drew
        console.error('route drew nothing on '+where);
        foPageFailed(where,null,'The '+where+' page finished loading but drew nothing.');
      }catch(e){}
    },5000);
  }catch(e){}
}
function route(){
  try{
  // an empty hash becomes a real #/circuit hash (not just a default) so the
  // overlay page renderers - which gate on location.hash - actually paint
  if(!location.hash){location.hash='#/home';return}
  const h=location.hash;
  const [path,qs]=h.slice(2).split('?');
  const q={};if(qs)for(const kv of qs.split('&')){const [k,v]=kv.split('=');q[k]=decodeURIComponent(v||'')}
  App.page=path||'circuit';
  // Circuit-only era: the club dashboard and the league/office/training
  // surfaces are retired; any old link or bookmark lands on the Circuit.
  // training returned to life as The Nets (league/18-training-nets.js)
  const GONE={club:1,office:1,nets:1,stats:1,matches:1,transfers:1,story:1,friendly:1,scout:1,reports:1,commentary:1,calibration:1,editor:1,welcome:1,founder:1,create:1};
  if(GONE[App.page]){location.hash='#/home';App.page='home';return}
  // the conquest Circuit is retired; its hub folds into the repurposed World map
  if(App.page==='circuit'||App.page==='tour'){location.hash='#/world';App.page='world';return}
  // #9 Draft lock: a new player cannot navigate away until they've confirmed a legal squad.
  // founderConfirm sets fo_welcomed; until then, keep them in the draft/onboarding.
  try{
    if(!store('fo_welcomed') && App.page!=='manual' && App.page!=='help'){
      // the overlay front door (name your club) owns entry; park the page on
      // the league behind it (the Circuit hub is retired)
      if(App.page!=='home'){location.hash='#/home';return}
    }
  }catch(e){}
  document.querySelectorAll('#topbar a').forEach(a=>a.classList.toggle('on',a.dataset.nav===App.page));
  const P={club:pgClub,office:pgOffice,matches:pgMatches,squad:pgSquad,orders:pgOrders,players:pgPlayers,
    player:pgPlayer,nets:pgNets,stats:pgStats,commentary:pgCommentary,welcome:pgWelcome,match:pgMatch,scorecard:pgScorecard,calibration:pgCal,reports:pgReports,help:pgManual,manual:pgManual,editor:pgEditor};
  // Circuit-era pages paint themselves; dispatch them directly so a refresh
  // never flashes the retired club dashboard while their interval spins up
  const OV={home:'foRenderHome',league:'foRenderLeagueTablePage',nation:'foRenderNation',atlas:'foRenderLeague',planet:'foRenderPlanetPage',almanack:'foRenderAlmanackPage',star:'foRenderStarPage',wcmatch:'foRenderWcMatchPage',cup:'foRenderCup',circuit:'foRenderCircuit',city:'foRenderCity',tour:'foRenderTour',world:'foRenderWorld',boss:'foRenderBoss',side:'foRenderSide',wire:'foRenderWire',lore:'foRenderLore',report:'foRenderReport',ceremony:'foRenderCeremony',desk:'foRenderDesk',ledger:'foRenderLedger',training:'foRenderNetsPage',dossier:'foRenderScoutPage',milestones:'foRenderHonoursPage',whatif:'foRenderTimeMachinePage',fixtures:'foRenderFixturesPage',matchday:'foRenderMatchCentre',records:'foRenderRecordsPage',paper:'foRenderPaperPage',champions:'foRenderChampionsPage',worldclub:'foRenderWorldClubPage',natteams:'foRenderNationsPage',nations:'foRenderNationsPage',guide:'foRenderManualPage',watch:'foRenderWatchPage',rankings:'foRenderRankingsPage',team:'foRenderClubPage',academy:'foRenderAcademyPage',finance:'foRenderFinancePage',comps:'foRenderCompsPage',market:'foRenderMarketPage',table:'foRenderStandingsPage',today:'foRenderTodayPage',team:'foRenderTeamPage'}[App.page];
  if(P[App.page])P[App.page](q);
  // A RENDERER THAT THROWS USED TO VANISH. This catch was empty, so a page
  // whose painter hit an error left the topbar, the clock and the nav in place
  // over an entirely blank body - no message, no console line anyone would
  // think to look for, no way out. Report it, and put something on the screen
  // that says what happened and offers somewhere else to go.
  else if(OV&&typeof window[OV]==='function'){try{window[OV]()}catch(eOv){
    try{console.error('route renderer failed on '+App.page,eOv)}catch(e3){}
    foPageFailed(App.page,eOv,'The '+App.page+' page hit an error while drawing.');
  }}
  else if(OV){/* overlay not parsed yet: leave the page blank, its interval paints */}
  else{location.hash='#/home';return}
  foBlankWatch(App.page);
  }catch(eRoute){
    // a broken page renderer must not freeze navigation for the whole session
    try{console.error('route failed on '+(App&&App.page),eRoute)}catch(e2){}
    try{foPageFailed(App&&App.page,eRoute,'This page could not be opened.')}catch(e4){}
  }finally{
    // first-class post-route hook: the league layer decorates the page here
    if(typeof window!=='undefined'&&typeof window.foAfterRoute==='function'){try{window.foAfterRoute()}catch(eAR){}}
  }
}
window.addEventListener('hashchange',route);

