function pgClub(){
  seasonInit();
  const t=userTeam();const S=App.season;
  const xi=pickXI(t);
  const rowsL=leagueRows();const pos=rowsL.findIndex(x=>x.nm===t.name)+1;
  const tbl=rowsL.map((x,i)=>`<tr ${x.nm===t.name?'style="background:#eef4ee"':''}><td>${i+1}</td><td>${esc(x.nm)}</td><td class="n">${x.p}</td><td class="n">${x.w}</td><td class="n">${x.l}</td><td class="n">${x.nrr>=0?'+':''}${x.nrr.toFixed(2)}</td><td class="n"><b>${x.pts}</b></td></tr>`).join('');
  // upcoming fixtures: user's next 3 from schedule
  const ups=[];
  for(let r=S.round;r<S.schedule.length&&ups.length<3;r++){
    for(const f of S.schedule[r]){
      if(f[0]!==App.teamIx&&f[1]!==App.teamIx)continue;
      if(S.played[fixtureKey(r,f)]!==undefined)continue;
      const home=GD.teams[f[0]];
      const d=new Date(2026,6,4);d.setDate(d.getDate()+7*r);
      ups.push(`<tr><td>${d.toLocaleDateString('en-GB',{day:'2-digit',month:'short'})} 11:00</td><td>One Day R${r+1}</td><td>${esc(GD.teams[f[0]===App.teamIx?f[1]:f[0]].name)}</td><td>@ ${esc(home.ground)} <span class="small">(${groundPitch(home.ground)})</span></td></tr>`);
    }}
  const last=App.results.slice(-3).reverse().map(r=>`<tr class="rowlink" onclick="location.hash='#/scorecard?i=${r.ix}'"><td>${r.date}</td><td>${esc(r.home)} v ${esc(r.away)}</td><td>${esc(r.result.text)}</td></tr>`).join('')||'<tr><td colspan=3 class="small">No matches played yet.</td></tr>';
  $('#page').innerHTML=crumb(t.name,'Club')+mpBanner()+
  `<div class="small" style="margin:-2px 0 6px">Round ${Math.min(S.round+1,9)}, Season 1 &nbsp;|&nbsp; <span id="clock"></span></div>
  <div class="grid2"><div class="col">
    <div class="panel"><h4>Club overview</h4><div class="pad"><table class="kv">
      <tr><td>Club</td><td><b>${esc(t.name)}</b></td></tr>
      <tr><td>Country</td><td>Netherlands</td></tr>
      <tr><td>Ground</td><td>${esc(t.ground)} <span class="small">(${groundPitch(t.ground)} pitch)</span></td></tr>
      <tr><td>League</td><td>One Day - Chat Division 1</td></tr>
      <tr><td>Position</td><td><b>${pos>0?pos:'-'}</b> of ${GD.teams.length}</td></tr>
      <tr><td>Manager</td><td>${esc(myMgrName()||'-')}</td></tr>
      </table>
      <div class="ctlrow"><span>Manage club:</span><select onchange="App.teamIx=+this.value;App.orders.batOrder=[];route()">${GD.teams.map((x,i)=>`<option value="${i}" ${i===App.teamIx?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div>
    </div></div>
    <div class="panel"><h4>Matches</h4><div class="pad"><table><tr><th>Date</th><th>Comp</th><th>Opponent</th><th>Venue</th></tr>${ups.join('')||'<tr><td colspan=4 class="small">Season complete.</td></tr>'}</table>
    <div class="small" style="margin-top:4px"><a href="#/orders">Set orders</a> · <a href="#/matches">Go to round</a></div></div></div>
    ${(App.news&&App.news.length)?`<div class="panel"><h4>News</h4><div class="pad">${App.news.slice(0,6).map(n=>`<div class="bl small">${esc(n)}</div>`).join('')}</div></div>`:''}
    <div class="panel"><h4>Recent results</h4><div class="pad"><table><tr><th>Date</th><th>Match</th><th>Result</th></tr>${last}</table></div></div>
  </div><div class="col">
    <div class="panel"><h4>League table</h4><div class="pad"><table><tr><th>#</th><th>Club</th><th class="n">P</th><th class="n">W</th><th class="n">L</th><th class="n">NRR</th><th class="n">Pts</th></tr>${tbl}</table></div></div>
    <div class="panel"><h4>Projected XI</h4><div class="pad"><table><tr><th>#</th><th>Player</th><th>Role</th><th class="n">Rating</th></tr>
    ${xi.map((p,i)=>`<tr><td>${i+1}</td><td>${playerLink(p)}${p.keeper?' \u2020':''}</td><td>${prole(p.role)}</td><td class="n">${p.rating}</td></tr>`).join('')}</table></div></div>
  </div></div>`;
  const tick=()=>{const el=document.getElementById('clock');if(!el)return false;
    el.textContent=new Date().toLocaleString('en-GB',{weekday:'short',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',second:'2-digit'});return true};
  tick();if(window.__clk)clearInterval(window.__clk);window.__clk=setInterval(()=>{if(!tick())clearInterval(window.__clk)},1000);
}
