      var r = (App.season && App.season.round) || 0;
      if (st.round !== r) { st = { round: r, pos: pos, prev: (st.round != null && st.round < r) ? st.pos : st.prev }; lsSet(k, JSON.stringify(st)); }
      else if (st.pos !== pos) { st.pos = pos; lsSet(k, JSON.stringify(st)); }
