      var byName = ix.filter(function (r) { return r.n.toLowerCase().indexOf(q) >= 0; });
      var byKw = ix.filter(function (r) { return r.kw && r.n.toLowerCase().indexOf(q) < 0 && r.kw.indexOf(q) >= 0; });
