    var wx0 = String(pend0.weather || "").toLowerCase();
    var newBallBites = pitch0 === "green" || pitch0 === "cracked" || /overcast|humid|misty|drizzle/.test(wx0);
    var turnLater = pitch0 === "dry" || pitch0 === "slow" || pitch0 === "twoPaced";
