      var segs = keys.map(function (k) {
        var c = FO_SK_COLOR[k] || "#667085";
        return "<i style='width:" + w[k] + "%;background:" + c + "' title='" + E(foSkillLabel(k)) + " " + w[k] + "%'>" + (w[k] >= 20 ? "<em>" + w[k] + "</em>" : "") + "</i>";
      }).join("");
