      // the (transparent) header, fill the viewport, kill any leftover scroll
      el.style.marginTop = "0px"; el.style.marginBottom = "0px";
      var top = el.getBoundingClientRect().top + window.scrollY;
      el.style.marginTop = (-top) + "px";
