        dx = Math.max(-bx, Math.min(bx, dx)); dy = Math.max(-by, Math.min(by, dy));
        mapEl.style.transform = "translate(calc(-50% + " + dx + "px),calc(-50% + " + dy + "px)) scale(" + Z + ")";
        mapEl.style.setProperty("--wz", Z);
