      host.addEventListener("wheel", function (ev) {
        ev.preventDefault();
        var r0 = host.getBoundingClientRect();
        zoomW((mapEl.__z || 1) * (ev.deltaY < 0 ? 1.16 : 0.86), ev.clientX - r0.left, ev.clientY - r0.top);
      }, { passive: false });
      var zi = page.querySelector("#fo-wz-in"), zo = page.querySelector("#fo-wz-out");
      if (zi) zi.addEventListener("click", function () { zoomW((mapEl.__z || 1) * 1.35); });
