        if (h.bbNm && h.bbW >= 0 && (!bestFig || h.bbW > bestFig.w || (h.bbW === bestFig.w && h.bbR < bestFig.r))) bestFig = { nm: h.bbNm, w: h.bbW, r: h.bbR };
