      ".fo-boss-form em.w{background:rgba(95,211,154,.18);color:#7fe3b0;border:1px solid rgba(95,211,154,.4)}",
      ".fo-boss-form em.l{background:rgba(224,110,110,.16);color:#f0a2a2;border:1px solid rgba(224,110,110,.36)}",
