        c.lineWidth = s.dash ? 1.6 : 2.2;
        s.pts.forEach(function (p, i) { var px = x(p[0]), py = y(p[1]); if (i === 0) c.moveTo(px, py); else c.lineTo(px, py); });
        c.stroke();
